CREATE TABLE produtos (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, sku VARCHAR(40) NOT NULL UNIQUE, nome VARCHAR(100) NOT NULL, preco NUMERIC(12,2) NOT NULL CHECK(preco>0), estoque INTEGER NOT NULL CHECK(estoque>=0 AND estoque<=1000000));
CREATE TABLE pedidos (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, cliente VARCHAR(80) NOT NULL, status VARCHAR(20) NOT NULL CHECK(status IN ('RASCUNHO','CONFIRMADO','CANCELADO')), criado_em TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE pedido_itens (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, pedido_id BIGINT NOT NULL REFERENCES pedidos(id), produto_id BIGINT NOT NULL REFERENCES produtos(id), produto_nome VARCHAR(100) NOT NULL, quantidade INTEGER NOT NULL CHECK(quantidade>0 AND quantidade<=9999), preco_unitario NUMERIC(12,2) NOT NULL CHECK(preco_unitario>0), UNIQUE(pedido_id,produto_id));
CREATE INDEX idx_itens_pedido ON pedido_itens(pedido_id);
CREATE TABLE movimentacoes (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, produto_id BIGINT NOT NULL REFERENCES produtos(id), pedido_id BIGINT REFERENCES pedidos(id), quantidade INTEGER NOT NULL CHECK(quantidade<>0), motivo VARCHAR(40) NOT NULL, criado_em TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE INDEX idx_movimentos_data ON movimentacoes(criado_em);

